import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { PhotoSettings, PhotoSize, AppConfig, BackgroundType } from '../types';
import { savePhotoToCloud } from '../services/databaseService';

// Sub-components
import PrintSidebar from './PrintSidebar';
import PrintSheetView from './PrintSheetView';

interface PrintPreviewProps {
  processedImage: string;
  size: PhotoSize;
  settings: PhotoSettings;
  onBack: () => void;
  onNew: () => void;
  onSaved?: () => void;
  onHome: () => void;
  config: AppConfig;
}

const PrintPreview: React.FC<PrintPreviewProps> = ({ 
  processedImage, size, settings, onBack, onNew, onHome, config
}) => {
  const [isSaving, setIsSaving] = useState(false);
  const [realPhotoId, setRealPhotoId] = useState<string | null>(null);
  const [qrUrl, setQrUrl] = useState<string>('');
  const [sheetImages, setSheetImages] = useState<string[]>([]);

  const layout = size === PhotoSize.SIZE_3X4 ? { cols: 4, rows: 4, photoW_mm: 30, photoH_mm: 40, rotated: false, maxOnSheet: 16 }
              : size === PhotoSize.SIZE_5X5 ? { cols: 2, rows: 3, photoW_mm: 50, photoH_mm: 50, rotated: false, maxOnSheet: 6 }
              : { cols: 2, rows: 4, photoW_mm: 60, photoH_mm: 40, rotated: true, maxOnSheet: 8 };

  const totalSheets = Math.ceil(settings.printQuantity / layout.maxOnSheet);

  const loadImage = (src: string): Promise<HTMLImageElement> => new Promise((res, rej) => { const img = new Image(); img.crossOrigin="anonymous"; img.onload=()=>res(img); img.onerror=rej; img.src=src; });

  const generateSheetCanvas = async (sheetIdx: number, photoImg: HTMLImageElement, logoImg: HTMLImageElement | null, qrImg: HTMLImageElement | null): Promise<string> => {
        const DPI = 300; const MM_TO_PX = DPI / 25.4;
        const canvas = document.createElement('canvas'); 
        canvas.width = Math.ceil(130 * MM_TO_PX); 
        canvas.height = Math.ceil(180 * MM_TO_PX);

        const ctx = canvas.getContext('2d'); if (!ctx) throw new Error();
        ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, canvas.width, canvas.height);

        const end = Math.min((sheetIdx + 1) * layout.maxOnSheet, settings.printQuantity);
        const count = end - (sheetIdx * layout.maxOnSheet);
        const cellW = layout.photoW_mm * MM_TO_PX; const cellH = layout.photoH_mm * MM_TO_PX;
        const startX = (canvas.width - (layout.cols * cellW)) / 2; const startY = 5 * MM_TO_PX; 

        const bgCol = settings.background === BackgroundType.ORIGINAL ? null : (config.backgroundConfig.find(b => b.type === settings.background)?.hexColor || '#ffffff');

        let lastPhotoY = startY;
        for (let i = 0; i < count; i++) {
            const row = Math.floor(i / layout.cols);
            const x = startX + (i % layout.cols) * cellW; 
            const y = startY + row * cellH;
            lastPhotoY = Math.max(lastPhotoY, y + cellH);

            ctx.save(); ctx.beginPath(); ctx.rect(x, y, cellW, cellH); ctx.clip();
            if (bgCol) { ctx.fillStyle = bgCol; ctx.fillRect(x, y, cellW, cellH); }
            if (layout.rotated) { ctx.translate(x + cellW/2, y + cellH/2); ctx.rotate(-Math.PI/2); ctx.drawImage(photoImg, -cellH/2, -cellW/2, cellH, cellW); }
            else ctx.drawImage(photoImg, x, y, cellW, cellH);
            ctx.restore(); 

            ctx.strokeStyle = '#d1d5db'; 
            ctx.setLineDash([15, 15]); 
            ctx.strokeRect(x, y, cellW, cellH);
        }

        // FOOTER LINH ĐỘNG: Nằm ngay dưới hàng ảnh cuối cùng
        const footerH = 15 * MM_TO_PX;
        const footerGap = 5 * MM_TO_PX; // Khoảng cách 5mm từ ảnh đến footer
        let footerY = lastPhotoY + footerGap;

        // Đảm bảo footer không vượt quá giới hạn trang (trường hợp in đầy khổ)
        if (footerY + footerH > canvas.height) {
          footerY = canvas.height - footerH;
        }

        ctx.setLineDash([]); // Reset line dash cho footer
        ctx.fillStyle = '#ffffff'; 
        ctx.fillRect(0, footerY, canvas.width, footerH);

        // Đường kẻ ngăn cách footer
        ctx.beginPath(); 
        ctx.moveTo(0, footerY); 
        ctx.lineTo(canvas.width, footerY); 
        ctx.strokeStyle = '#000000'; 
        ctx.lineWidth = 2; 
        ctx.stroke();

        let lo = 5 * MM_TO_PX; 
        if (logoImg) { 
          const lh = 10 * MM_TO_PX; 
          const lw = logoImg.width * (lh / logoImg.height); 
          ctx.drawImage(logoImg, lo, footerY + 2.5 * MM_TO_PX, lw, lh); 
          lo += lw + 3 * MM_TO_PX; 
        }

        ctx.fillStyle = '#000000'; 
        ctx.font = `bold ${5 * MM_TO_PX}px sans-serif`; 
        ctx.textBaseline = 'middle';
        ctx.fillText(config.shopName, lo, footerY + (footerH / 2));

        if (qrImg) {
          const qrSize = 12 * MM_TO_PX;
          ctx.drawImage(qrImg, canvas.width - qrSize - 5 * MM_TO_PX, footerY + (footerH - qrSize) / 2, qrSize, qrSize);
        }

        return canvas.toDataURL('image/png');
  };

  useEffect(() => {
     if (!qrUrl) return; 
     (async () => {
         try {
             const [p, l, q] = await Promise.all([loadImage(processedImage), config.logoUrl ? loadImage(config.logoUrl).catch(() => null) : null, loadImage(qrUrl).catch(() => null)]);
             const sheets = []; for (let i = 0; i < totalSheets; i++) sheets.push(await generateSheetCanvas(i, p, l, q));
             setSheetImages(sheets);
         } catch {}
     })();
  }, [qrUrl, processedImage, totalSheets, config]);

  useEffect(() => {
    (async () => {
      setIsSaving(true); const id = await savePhotoToCloud({ id: 'temp', dataUrl: processedImage, timestamp: Date.now(), settings });
      if (id) { setRealPhotoId(id); const v = `${window.location.href.split('?')[0]}?photoId=${id}`; setQrUrl(`https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(v)}&ecc=H`); }
      setIsSaving(false);
    })();
  }, []); 

  const handleDownload = () => { sheetImages.forEach((d, i) => { const l = document.createElement('a'); l.href = d; l.download = `Photo-Sheet-${i+1}.png`; l.click(); }); };

  return (
    <div className="flex flex-col h-full bg-slate-100 relative">
      {document.getElementById('print-mount') && createPortal(<div className="print-portal-root">{sheetImages.map((s, i) => <div key={i} className="sheet-page"><img src={s} alt="" /></div>)}</div>, document.getElementById('print-mount')!)}
      <header className="bg-white shadow-sm p-4 flex justify-between items-center z-20">
        <h1 className="text-xl font-extrabold text-slate-800 flex items-center gap-2">🖨️ Print Preview</h1>
        <button onClick={onBack} className="px-4 py-2 text-sm font-bold text-slate-600 hover:bg-slate-100 rounded-lg">Quay lại</button>
      </header>
      <div className="flex-1 overflow-hidden flex justify-center items-start gap-8 p-8 bg-slate-100">
        <PrintSheetView sheetImages={sheetImages} isSaving={isSaving} />
        <PrintSidebar 
            photoId={realPhotoId}
            isSaving={isSaving}
            sheetImages={sheetImages}
            qrUrl={qrUrl}
            settings={settings}
            config={config}
            onPrint={() => window.print()}
            onDownload={handleDownload}
            onHome={onHome}
        />
      </div>
    </div>
  );
};

export default PrintPreview;

import React, { useEffect, useState } from 'react';
import { getPhotoById } from '../services/databaseService';
import { SavedPhoto, PhotoSize, AppConfig } from '../types';

interface PhotoViewerProps {
  photoId: string;
  config?: AppConfig; // Optional config for branding
}

const PhotoViewer: React.FC<PhotoViewerProps> = ({ photoId, config }) => {
  const [photo, setPhoto] = useState<SavedPhoto | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  // Sheet Generation State
  const [isGenerating, setIsGenerating] = useState(false);

  // Determine current URL for QR
  const getCurrentUrl = () => {
    const baseUrl = window.location.href.split('?')[0];
    return `${baseUrl}?photoId=${photoId}`;
  };

  useEffect(() => {
    const fetchPhoto = async () => {
      setLoading(true);
      const data = await getPhotoById(photoId);
      if (data) {
        setPhoto(data);
      } else {
        setError('Không tìm thấy ảnh hoặc ảnh đã bị xóa.');
      }
      setLoading(false);
    };
    fetchPhoto();
  }, [photoId]);

  // --- DOWNLOAD HANDLERS ---
  const downloadImage = (dataUrl: string, filename: string) => {
    const link = document.createElement('a');
    link.href = dataUrl;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleDownloadSingle = () => {
    if (!photo) return;
    const canvas = document.createElement('canvas');
    const img = new Image();
    img.src = photo.dataUrl;
    img.crossOrigin = "anonymous";
    img.onload = () => {
        canvas.width = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
            ctx.drawImage(img, 0, 0);
            const pngData = canvas.toDataURL('image/png');
            downloadImage(pngData, `Photo-${photo.id}-Single.png`);
        }
    };
  };

  // Helper to load image for Canvas
  const loadImage = (src: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => resolve(img);
        img.onerror = () => reject(new Error(`Failed to load image`));
        img.src = src;
    });
  };

  const handleDownloadSheet = async () => {
    if (!photo) return;
    setIsGenerating(true);

    try {
        // CONFIG CONSTANTS
        const DPI = 300;
        const MM_TO_PX = DPI / 25.4;
        const SHEET_W = Math.ceil(130 * MM_TO_PX);
        const SHEET_H = Math.ceil(180 * MM_TO_PX);

        const canvas = document.createElement('canvas');
        canvas.width = SHEET_W;
        canvas.height = SHEET_H;
        const ctx = canvas.getContext('2d');
        if (!ctx) throw new Error("Canvas init failed");

        // 1. Fill White Background
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // 2. Prepare Resources (ROBUST LOADING)
        const photoUrl = photo.dataUrl;
        const shopLogoUrl = config?.logoUrl;
        const qrContent = getCurrentUrl();
        const qrApiUrl = `https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(qrContent)}&color=000000&bgcolor=FFFFFF&margin=0&ecc=H`;

        const [mainPhotoImg, logoImg, qrImg] = await Promise.all([
            loadImage(photoUrl),
            shopLogoUrl ? loadImage(shopLogoUrl).catch(() => null) : Promise.resolve(null),
            loadImage(qrApiUrl).catch(() => null)
        ]);

        // 3. Draw Photo Grid
        const size = photo.settings.size;
        let cols=2, rows=4, photoW_mm=60, photoH_mm=40, rotated=true, maxOnSheet=8;

        if (size === PhotoSize.SIZE_3X4) {
            cols = 4; rows = 4; photoW_mm = 30; photoH_mm = 40; rotated = false; maxOnSheet = 16;
        } else if (size === PhotoSize.SIZE_5X5) {
            cols = 2; rows = 3; photoW_mm = 50; photoH_mm = 50; rotated = false; maxOnSheet = 6;
        }

        const cellW = photoW_mm * MM_TO_PX;
        const cellH = photoH_mm * MM_TO_PX;
        const gridW = cols * cellW;
        const startY = 5 * MM_TO_PX; // Top margin
        const startX = (canvas.width - gridW) / 2;

        let lastPhotoY = startY;
        for (let i = 0; i < maxOnSheet; i++) {
            const r = Math.floor(i / cols);
            const c = i % cols;
            const x = startX + c * cellW;
            const y = startY + r * cellH;
            lastPhotoY = Math.max(lastPhotoY, y + cellH);

            ctx.save();
            ctx.beginPath();
            ctx.rect(x, y, cellW, cellH);
            ctx.clip();

            if (rotated) {
                const cx = x + cellW / 2;
                const cy = y + cellH / 2;
                ctx.translate(cx, cy);
                ctx.rotate(-90 * Math.PI / 180);
                ctx.drawImage(mainPhotoImg, -cellH/2, -cellW/2, cellH, cellW); 
            } else {
                ctx.drawImage(mainPhotoImg, x, y, cellW, cellH);
            }
            ctx.restore();

            // Cut lines
            ctx.strokeStyle = '#d1d5db';
            ctx.lineWidth = 1;
            ctx.setLineDash([15, 15]);
            ctx.strokeRect(x, y, cellW, cellH);
        }

        // 4. Draw Dynamic Footer
        const footerH = 15 * MM_TO_PX; 
        const footerGap = 5 * MM_TO_PX;
        let footerY = lastPhotoY + footerGap;

        if (footerY + footerH > canvas.height) {
            footerY = canvas.height - footerH;
        }

        // Background
        ctx.setLineDash([]);
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, footerY, canvas.width, footerH);

        // Border
        ctx.beginPath();
        ctx.moveTo(0, footerY);
        ctx.lineTo(canvas.width, footerY);
        ctx.strokeStyle = '#000000';
        ctx.lineWidth = 2;
        ctx.stroke();

        const padding = 5 * MM_TO_PX;
        const contentY = footerY + footerH / 2;
        let leftOffset = padding;

        // --- DRAW LOGO IN FOOTER ---
        if (logoImg) {
            const logoH = 10 * MM_TO_PX;
            const scale = logoH / logoImg.height;
            const logoW = logoImg.width * scale;
            const logoY = contentY - logoH / 2;

            ctx.drawImage(logoImg, leftOffset, logoY, logoW, logoH);
            leftOffset += logoW + (3 * MM_TO_PX);
        }

        // --- DRAW TEXT ---
        ctx.textAlign = 'left';
        ctx.fillStyle = '#000000';
        const nameSize = 5 * MM_TO_PX;
        ctx.font = `bold ${nameSize}px sans-serif`;
        ctx.textBaseline = 'bottom';
        const shopName = config?.shopName || "ID Photo Booth";
        ctx.fillText(shopName, leftOffset, contentY - (0.5 * MM_TO_PX));

        ctx.fillStyle = '#4b5563';
        const infoSize = 3.5 * MM_TO_PX;
        ctx.font = `${infoSize}px sans-serif`;
        ctx.textBaseline = 'top';
        const dateStr = new Date(photo.timestamp).toLocaleDateString('vi-VN');
        const footerText = config?.printFooterText || "Ảnh thẻ lấy ngay";
        ctx.fillText(`${footerText} | ${dateStr}`, leftOffset, contentY + (0.5 * MM_TO_PX));

        // --- DRAW QR CODE ---
        if (qrImg) {
            const qrSize = 12 * MM_TO_PX; 
            const qrX = canvas.width - padding - qrSize;
            const qrY = contentY - qrSize / 2;
            ctx.drawImage(qrImg, qrX, qrY, qrSize, qrSize);

            if (logoImg) {
                const centerLogoSize = qrSize * 0.25;
                const centerX = qrX + (qrSize - centerLogoSize) / 2;
                const centerY = qrY + (qrSize - centerLogoSize) / 2;
                ctx.fillStyle = '#ffffff';
                ctx.fillRect(centerX - 1, centerY - 1, centerLogoSize + 2, centerLogoSize + 2);
                ctx.drawImage(logoImg, centerX, centerY, centerLogoSize, centerLogoSize);
            }
        }

        const sheetDataUrl = canvas.toDataURL('image/png');
        downloadImage(sheetDataUrl, `Photo-${photo.id}-Sheet-13x18.png`);

    } catch (e) {
        console.error("Sheet generation failed", e);
        alert("Không thể tạo file in. Vui lòng thử lại.");
    } finally {
        setIsGenerating(false);
    }
  };

  if (loading) return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center bg-gray-50 p-4">
        <div className="w-12 h-12 border-4 border-brand-200 border-t-brand-600 rounded-full animate-spin mb-4"></div>
        <p className="text-gray-500 font-medium animate-pulse">Đang tải ảnh từ Cloud...</p>
    </div>
  );

  if (error || !photo) return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center bg-gray-50 p-6 text-center">
        <div className="w-16 h-16 bg-red-100 text-red-500 rounded-full flex items-center justify-center mb-4 shadow-sm">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
        </div>
        <h2 className="text-xl font-bold text-gray-800 mb-2">Không tìm thấy ảnh</h2>
        <p className="text-gray-600 mb-6 max-w-xs mx-auto">{error}</p>
        <a href="/" className="px-6 py-2.5 bg-gray-800 text-white rounded-xl font-bold hover:bg-black transition shadow-lg">Về trang chủ</a>
    </div>
  );

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-200 p-4 flex flex-col items-center">

       <div className="mb-4 md:mb-6 flex flex-col items-center animate-fadeIn">
          {config?.logoUrl ? (
             <img src={config.logoUrl} alt="Logo" className="h-12 md:h-16 w-auto object-contain mb-2 drop-shadow-sm" />
          ) : (
             <div className="w-10 h-10 md:w-12 md:h-12 bg-brand-600 rounded-2xl flex items-center justify-center text-white font-bold text-lg md:text-xl mb-2 shadow-lg">
               {config?.shopName?.charAt(0) || 'P'}
             </div>
          )}
          <span className="font-bold text-lg md:text-xl text-slate-800 text-center">{config?.shopName || 'ID Photo Booth'}</span>
       </div>

       <div className="max-w-4xl w-full bg-white rounded-3xl shadow-2xl overflow-hidden flex flex-col md:flex-row animate-fadeIn">

          <div className="w-full md:w-1/2 bg-slate-100 p-6 md:p-8 flex flex-col items-center justify-center border-b md:border-b-0 md:border-r border-slate-200 relative">
             <div className="absolute top-4 left-4 bg-white/80 backdrop-blur px-3 py-1 rounded-full text-xs font-bold text-slate-500 shadow-sm">
                ID: {photo.id}
             </div>

             <div className="relative shadow-2xl rounded-lg overflow-hidden border-4 border-white transform transition hover:scale-105 duration-300">
                 <img src={photo.dataUrl} className="max-h-[300px] md:max-h-[400px] w-auto object-contain" alt="ID Photo" />
             </div>

             <div className="mt-6 flex flex-wrap justify-center gap-3">
                <span className="px-3 py-1.5 bg-white border border-slate-200 text-slate-600 text-xs font-bold rounded-lg shadow-sm">
                   {photo.settings.size === PhotoSize.SIZE_3X4 ? '3x4 cm' : photo.settings.size === PhotoSize.SIZE_5X5 ? '5x5 cm' : '4x6 cm'}
                </span>
                <span className="px-3 py-1.5 bg-white border border-slate-200 text-slate-600 text-xs font-bold rounded-lg shadow-sm">
                   {new Date(photo.timestamp).toLocaleDateString('vi-VN')}
                </span>
             </div>
          </div>

          <div className="w-full md:w-1/2 p-6 md:p-8 flex flex-col">
             <div className="mb-6 md:mb-8 text-center md:text-left">
                <h2 className="text-xl md:text-2xl font-black text-slate-800 mb-2">Xin chào! 👋</h2>
                <p className="text-slate-500 text-sm">Ảnh của bạn đã sẵn sàng. Bạn có thể tải về điện thoại hoặc tải file in chất lượng cao để in ấn.</p>
             </div>

             <div className="flex-1 space-y-4">
                 <button 
                    onClick={handleDownloadSingle} 
                    className="group w-full p-4 bg-white border-2 border-slate-100 hover:border-brand-500 hover:bg-brand-50 rounded-2xl transition-all flex items-center gap-4 text-left shadow-sm hover:shadow-md active:scale-95"
                 >
                    <div className="w-10 h-10 md:w-12 md:h-12 rounded-full bg-blue-100 text-brand-600 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform">
                       <svg className="w-5 h-5 md:w-6 md:h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"></path></svg>
                    </div>
                    <div>
                       <div className="font-bold text-slate-800 group-hover:text-brand-700 text-sm md:text-base">Tải Ảnh Thẻ (PNG)</div>
                       <div className="text-xs text-slate-400">Ảnh đơn, Chất lượng gốc (HQ)</div>
                    </div>
                 </button>

                 <button 
                    onClick={handleDownloadSheet}
                    disabled={isGenerating} 
                    className="group w-full p-4 bg-brand-600 hover:bg-brand-700 rounded-2xl transition-all flex items-center gap-4 text-left shadow-lg shadow-brand-500/30 active:scale-95"
                 >
                    <div className="w-10 h-10 md:w-12 md:h-12 rounded-full bg-white/20 text-white flex items-center justify-center shrink-0">
                        {isGenerating ? (
                           <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                        ) : (
                           <svg className="w-5 h-5 md:w-6 md:h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
                        )}
                    </div>
                    <div>
                       <div className="font-bold text-white text-sm md:text-base">Tải File In (Sheet 13x18)</div>
                       <div className="text-xs text-brand-100 opacity-80">Đã dàn trang (PNG HQ)</div>
                    </div>
                 </button>
             </div>

             <div className="mt-8 pt-6 border-t border-slate-100 flex flex-col items-center">
                 <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-4">Quét mã để chia sẻ</p>
                 <div className="relative p-2 bg-white rounded-xl shadow-md border border-slate-100">
                    <img 
                      src={`https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(getCurrentUrl())}&color=000000&bgcolor=FFFFFF&margin=0&ecc=H`} 
                      className="w-28 h-28 md:w-32 md:h-32"
                      alt="QR"
                    />
                    {config?.logoUrl && (
                        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-8 h-8 bg-white rounded-full p-0.5 shadow-sm border border-slate-100 flex items-center justify-center">
                            <img src={config.logoUrl} className="w-full h-full object-contain rounded-full" alt="Logo" />
                        </div>
                    )}
                 </div>
             </div>
          </div>
       </div>

       <div className="mt-6 text-xs text-slate-400 font-medium text-center pb-8 flex flex-col items-center">
         {config?.logoUrl && (
             <img src={config.logoUrl} className="h-6 w-auto opacity-50 mb-2 grayscale" alt="Logo Footer" />
         )}
         <p>Hotline: {config?.contactPhone}</p>
         <p className="mt-1">© {new Date().getFullYear()} {config?.shopName || 'ID Photo Booth Pro'}</p>
       </div>
    </div>
  );
};

export default PhotoViewer;

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { PhotoSettings, PhotoSize, AppConfig, BackgroundType } from '../types';
import { savePhotoToCloud } from '../services/databaseService';

// Sub-components
import PrintSidebar from './PrintSidebar';
import PrintSheetView from './PrintSheetView';

interface PrintPreviewProps {
  processedImage: string;
  size: PhotoSize;
  settings: PhotoSettings;
  onBack: () => void;
  onNew: () => void;
  onSaved?: () => void;
  onHome: () => void;
  config: AppConfig;
}

const PrintPreview: React.FC<PrintPreviewProps> = ({ 
  processedImage, size, settings, onBack, onNew, onHome, config
}) => {
  const [isSaving, setIsSaving] = useState(false);
  const [realPhotoId, setRealPhotoId] = useState<string | null>(null);
  const [qrUrl, setQrUrl] = useState<string>('');
  const [sheetImages, setSheetImages] = useState<string[]>([]);

  const layout = size === PhotoSize.SIZE_3X4 ? { cols: 4, rows: 4, photoW_mm: 30, photoH_mm: 40, rotated: false, maxOnSheet: 16 }
              : size === PhotoSize.SIZE_5X5 ? { cols: 2, rows: 3, photoW_mm: 50, photoH_mm: 50, rotated: false, maxOnSheet: 6 }
              : { cols: 2, rows: 4, photoW_mm: 60, photoH_mm: 40, rotated: true, maxOnSheet: 8 };

  const totalSheets = Math.ceil(settings.printQuantity / layout.maxOnSheet);

  const loadImage = (src: string): Promise<HTMLImageElement> => new Promise((res, rej) => { const img = new Image(); img.crossOrigin="anonymous"; img.onload=()=>res(img); img.onerror=rej; img.src=src; });

  const generateSheetCanvas = async (sheetIdx: number, photoImg: HTMLImageElement, logoImg: HTMLImageElement | null, qrImg: HTMLImageElement | null): Promise<string> => {
        const DPI = 300; const MM_TO_PX = DPI / 25.4;
        const canvas = document.createElement('canvas'); 
        canvas.width = Math.ceil(130 * MM_TO_PX); 
        canvas.height = Math.ceil(180 * MM_TO_PX);

        const ctx = canvas.getContext('2d'); if (!ctx) throw new Error();
        ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, canvas.width, canvas.height);

        const end = Math.min((sheetIdx + 1) * layout.maxOnSheet, settings.printQuantity);
        const count = end - (sheetIdx * layout.maxOnSheet);
        const cellW = layout.photoW_mm * MM_TO_PX; const cellH = layout.photoH_mm * MM_TO_PX;
        const startX = (canvas.width - (layout.cols * cellW)) / 2; const startY = 5 * MM_TO_PX; 

        const bgCol = settings.background === BackgroundType.ORIGINAL ? null : (config.backgroundConfig.find(b => b.type === settings.background)?.hexColor || '#ffffff');

        let lastPhotoY = startY;
        for (let i = 0; i < count; i++) {
            const row = Math.floor(i / layout.cols);
            const x = startX + (i % layout.cols) * cellW; 
            const y = startY + row * cellH;
            lastPhotoY = Math.max(lastPhotoY, y + cellH);

            ctx.save(); ctx.beginPath(); ctx.rect(x, y, cellW, cellH); ctx.clip();
            if (bgCol) { ctx.fillStyle = bgCol; ctx.fillRect(x, y, cellW, cellH); }
            if (layout.rotated) { ctx.translate(x + cellW/2, y + cellH/2); ctx.rotate(-Math.PI/2); ctx.drawImage(photoImg, -cellH/2, -cellW/2, cellH, cellW); }
            else ctx.drawImage(photoImg, x, y, cellW, cellH);
            ctx.restore(); 

            ctx.strokeStyle = '#d1d5db'; 
            ctx.setLineDash([15, 15]); 
            ctx.strokeRect(x, y, cellW, cellH);
        }

        // --- DYNAMIC FOOTER LOGIC ---
        const footerH = 15 * MM_TO_PX;
        const footerGap = 5 * MM_TO_PX; 
        let footerY = lastPhotoY + footerGap;

        // Ensure footer doesn't exceed page bounds if grid is full
        if (footerY + footerH > canvas.height) {
          footerY = canvas.height - footerH;
        }

        ctx.setLineDash([]); 
        ctx.fillStyle = '#ffffff'; 
        // Fill white from footer top to the bottom of the page
        ctx.fillRect(0, footerY, canvas.width, canvas.height - footerY);

        // Horizontal separation line
        ctx.beginPath(); 
        ctx.moveTo(0, footerY); 
        ctx.lineTo(canvas.width, footerY); 
        ctx.strokeStyle = '#333333'; 
        ctx.lineWidth = 0.5 * MM_TO_PX; 
        ctx.stroke();

        const contentY = footerY + footerH / 2;
        const padding = 5 * MM_TO_PX;
        let leftOffset = padding;

        // Draw Shop Logo
        if (logoImg) { 
          const lh = 8 * MM_TO_PX; 
          const lw = logoImg.width * (lh / logoImg.height); 
          ctx.drawImage(logoImg, leftOffset, contentY - lh/2, lw, lh); 
          leftOffset += lw + 3 * MM_TO_PX; 
        }

        // Draw Shop Name & Footer Subtext
        ctx.fillStyle = '#000000'; 
        ctx.font = `bold ${4 * MM_TO_PX}px sans-serif`; 
        ctx.textBaseline = 'middle';
        ctx.textAlign = 'left';
        ctx.fillText(config.shopName, leftOffset, contentY - 2 * MM_TO_PX);

        ctx.fillStyle = '#666666';
        ctx.font = `${2.5 * MM_TO_PX}px sans-serif`;
        ctx.fillText(config.printFooterText || "Dịch vụ chụp ảnh thẻ lấy ngay", leftOffset, contentY + 2.5 * MM_TO_PX);

        // Draw QR Code on the right
        if (qrImg) {
          const qrSize = 10 * MM_TO_PX;
          ctx.drawImage(qrImg, canvas.width - qrSize - padding, contentY - qrSize/2, qrSize, qrSize);
        }

        return canvas.toDataURL('image/png');
  };

  useEffect(() => {
     if (!qrUrl) return; 
     (async () => {
         try {
             const [p, l, q] = await Promise.all([loadImage(processedImage), config.logoUrl ? loadImage(config.logoUrl).catch(() => null) : null, loadImage(qrUrl).catch(() => null)]);
             const sheets = []; for (let i = 0; i < totalSheets; i++) sheets.push(await generateSheetCanvas(i, p, l, q));
             setSheetImages(sheets);
         } catch {}
     })();
  }, [qrUrl, processedImage, totalSheets, config]);

  useEffect(() => {
    (async () => {
      setIsSaving(true); const id = await savePhotoToCloud({ id: 'temp', dataUrl: processedImage, timestamp: Date.now(), settings });
      if (id) { setRealPhotoId(id); const v = `${window.location.href.split('?')[0]}?photoId=${id}`; setQrUrl(`https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(v)}&ecc=H`); }
      setIsSaving(false);
    })();
  }, []); 

  const handleDownload = () => { sheetImages.forEach((d, i) => { const l = document.createElement('a'); l.href = d; l.download = `Photo-Sheet-${i+1}.png`; l.click(); }); };

  return (
    <div className="flex flex-col h-full bg-slate-100 relative">
      {document.getElementById('print-mount') && createPortal(<div className="print-portal-root">{sheetImages.map((s, i) => <div key={i} className="sheet-page"><img src={s} alt="" /></div>)}</div>, document.getElementById('print-mount')!)}
      <header className="bg-white shadow-sm p-4 flex justify-between items-center z-20">
        <h1 className="text-xl font-extrabold text-slate-800 flex items-center gap-2">🖨️ Print Preview</h1>
        <button onClick={onBack} className="px-4 py-2 text-sm font-bold text-slate-600 hover:bg-slate-100 rounded-lg">Quay lại</button>
      </header>
      <div className="flex-1 overflow-hidden flex justify-center items-start gap-8 p-8 bg-slate-100">
        <PrintSheetView sheetImages={sheetImages} isSaving={isSaving} />
        <PrintSidebar 
            photoId={realPhotoId}
            isSaving={isSaving}
            sheetImages={sheetImages}
            qrUrl={qrUrl}
            settings={settings}
            config={config}
            onPrint={() => window.print()}
            onDownload={handleDownload}
            onHome={onHome}
        />
      </div>
    </div>
  );
};

export default PrintPreview;

import React, { useEffect, useState } from 'react';
import { getPhotoById } from '../services/databaseService';
import { SavedPhoto, PhotoSize, AppConfig } from '../types';

interface PhotoViewerProps {
  photoId: string;
  config?: AppConfig; // Optional config for branding
}

const PhotoViewer: React.FC<PhotoViewerProps> = ({ photoId, config }) => {
  const [photo, setPhoto] = useState<SavedPhoto | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  // Sheet Generation State
  const [isGenerating, setIsGenerating] = useState(false);

  // Determine current URL for QR
  const getCurrentUrl = () => {
    const baseUrl = window.location.href.split('?')[0];
    return `${baseUrl}?photoId=${photoId}`;
  };

  useEffect(() => {
    const fetchPhoto = async () => {
      setLoading(true);
      const data = await getPhotoById(photoId);
      if (data) {
        setPhoto(data);
      } else {
        setError('Không tìm thấy ảnh hoặc ảnh đã bị xóa.');
      }
      setLoading(false);
    };
    fetchPhoto();
  }, [photoId]);

  // --- DOWNLOAD HANDLERS ---
  const downloadImage = (dataUrl: string, filename: string) => {
    const link = document.createElement('a');
    link.href = dataUrl;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleDownloadSingle = () => {
    if (!photo) return;
    const canvas = document.createElement('canvas');
    const img = new Image();
    img.src = photo.dataUrl;
    img.crossOrigin = "anonymous";
    img.onload = () => {
        canvas.width = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
            ctx.drawImage(img, 0, 0);
            const pngData = canvas.toDataURL('image/png');
            downloadImage(pngData, `Photo-${photo.id}-Single.png`);
        }
    };
  };

  // Helper to load image for Canvas
  const loadImage = (src: string): Promise<HTMLImageElement> => {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.onload = () => resolve(img);
        img.onerror = () => reject(new Error(`Failed to load image`));
        img.src = src;
    });
  };

  const handleDownloadSheet = async () => {
    if (!photo) return;
    setIsGenerating(true);

    try {
        // CONFIG CONSTANTS
        const DPI = 300;
        const MM_TO_PX = DPI / 25.4;
        const SHEET_W = Math.ceil(130 * MM_TO_PX);
        const SHEET_H = Math.ceil(180 * MM_TO_PX);

        const canvas = document.createElement('canvas');
        canvas.width = SHEET_W;
        canvas.height = SHEET_H;
        const ctx = canvas.getContext('2d');
        if (!ctx) throw new Error("Canvas init failed");

        // 1. Fill White Background
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // 2. Prepare Resources (ROBUST LOADING)
        const photoUrl = photo.dataUrl;
        const shopLogoUrl = config?.logoUrl;
        const qrContent = getCurrentUrl();
        const qrApiUrl = `https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(qrContent)}&color=000000&bgcolor=FFFFFF&margin=0&ecc=H`;

        const [mainPhotoImg, logoImg, qrImg] = await Promise.all([
            loadImage(photoUrl),
            shopLogoUrl ? loadImage(shopLogoUrl).catch(() => null) : Promise.resolve(null),
            loadImage(qrApiUrl).catch(() => null)
        ]);

        // 3. Draw Photo Grid
        const size = photo.settings.size;
        let cols=2, rows=4, photoW_mm=60, photoH_mm=40, rotated=true, maxOnSheet=8;

        if (size === PhotoSize.SIZE_3X4) {
            cols = 4; rows = 4; photoW_mm = 30; photoH_mm = 40; rotated = false; maxOnSheet = 16;
        } else if (size === PhotoSize.SIZE_5X5) {
            cols = 2; rows = 3; photoW_mm = 50; photoH_mm = 50; rotated = false; maxOnSheet = 6;
        }

        const cellW = photoW_mm * MM_TO_PX;
        const cellH = photoH_mm * MM_TO_PX;
        const gridW = cols * cellW;
        const startY = 5 * MM_TO_PX; // Top margin
        const startX = (canvas.width - gridW) / 2;

        let lastPhotoY = startY;
        for (let i = 0; i < maxOnSheet; i++) {
            const r = Math.floor(i / cols);
            const c = i % cols;
            const x = startX + c * cellW;
            const y = startY + r * cellH;
            lastPhotoY = Math.max(lastPhotoY, y + cellH);

            ctx.save();
            ctx.beginPath();
            ctx.rect(x, y, cellW, cellH);
            ctx.clip();

            if (rotated) {
                const cx = x + cellW / 2;
                const cy = y + cellH / 2;
                ctx.translate(cx, cy);
                ctx.rotate(-90 * Math.PI / 180);
                ctx.drawImage(mainPhotoImg, -cellH/2, -cellW/2, cellH, cellW); 
            } else {
                ctx.drawImage(mainPhotoImg, x, y, cellW, cellH);
            }
            ctx.restore();

            // Cut lines
            ctx.strokeStyle = '#d1d5db';
            ctx.lineWidth = 1;
            ctx.setLineDash([15, 15]);
            ctx.strokeRect(x, y, cellW, cellH);
        }

        // --- DYNAMIC FOOTER LOGIC ---
        const footerH = 15 * MM_TO_PX; 
        const footerGap = 5 * MM_TO_PX;
        let footerY = lastPhotoY + footerGap;

        if (footerY + footerH > canvas.height) {
            footerY = canvas.height - footerH;
        }

        // Clear background for footer
        ctx.setLineDash([]);
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, footerY, canvas.width, canvas.height - footerY);

        // Border Line
        ctx.beginPath();
        ctx.moveTo(0, footerY);
        ctx.lineTo(canvas.width, footerY);
        ctx.strokeStyle = '#333333';
        ctx.lineWidth = 0.5 * MM_TO_PX;
        ctx.stroke();

        const padding = 5 * MM_TO_PX;
        const contentY = footerY + footerH / 2;
        let leftOffset = padding;

        // Draw Logo
        if (logoImg) {
            const logoH = 8 * MM_TO_PX;
            const scale = logoH / logoImg.height;
            const logoW = logoImg.width * scale;
            ctx.drawImage(logoImg, leftOffset, contentY - logoH / 2, logoW, logoH);
            leftOffset += logoW + (3 * MM_TO_PX);
        }

        // Draw Shop Brand
        ctx.textAlign = 'left';
        ctx.fillStyle = '#000000';
        ctx.font = `bold ${4 * MM_TO_PX}px sans-serif`;
        ctx.textBaseline = 'middle';
        const shopName = config?.shopName || "ID Photo Booth";
        ctx.fillText(shopName, leftOffset, contentY - 2 * MM_TO_PX);

        ctx.fillStyle = '#666666';
        ctx.font = `${2.5 * MM_TO_PX}px sans-serif`;
        const footerText = config?.printFooterText || "Dịch vụ chụp ảnh thẻ lấy ngay";
        ctx.fillText(footerText, leftOffset, contentY + 2.5 * MM_TO_PX);

        // Draw QR
        if (qrImg) {
            const qrSize = 10 * MM_TO_PX; 
            ctx.drawImage(qrImg, canvas.width - padding - qrSize, contentY - qrSize / 2, qrSize, qrSize);
        }

        const sheetDataUrl = canvas.toDataURL('image/png');
        downloadImage(sheetDataUrl, `Photo-${photo.id}-Sheet-13x18.png`);

    } catch (e) {
        console.error("Sheet generation failed", e);
        alert("Không thể tạo file in. Vui lòng thử lại.");
    } finally {
        setIsGenerating(false);
    }
  };

  if (loading) return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center bg-gray-50 p-4">
        <div className="w-12 h-12 border-4 border-brand-200 border-t-brand-600 rounded-full animate-spin mb-4"></div>
        <p className="text-gray-500 font-medium animate-pulse">Đang tải ảnh từ Cloud...</p>
    </div>
  );

  if (error || !photo) return (
    <div className="min-h-screen w-full flex flex-col items-center justify-center bg-gray-50 p-6 text-center">
        <div className="w-16 h-16 bg-red-100 text-red-500 rounded-full flex items-center justify-center mb-4 shadow-sm">
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
        </div>
        <h2 className="text-xl font-bold text-gray-800 mb-2">Không tìm thấy ảnh</h2>
        <p className="text-gray-600 mb-6 max-w-xs mx-auto">{error}</p>
        <a href="/" className="px-6 py-2.5 bg-gray-800 text-white rounded-xl font-bold hover:bg-black transition shadow-lg">Về trang chủ</a>
    </div>
  );

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-200 p-4 flex flex-col items-center">

       <div className="mb-4 md:mb-6 flex flex-col items-center animate-fadeIn">
          {config?.logoUrl ? (
             <img src={config.logoUrl} alt="Logo" className="h-12 md:h-16 w-auto object-contain mb-2 drop-shadow-sm" />
          ) : (
             <div className="w-10 h-10 md:w-12 md:h-12 bg-brand-600 rounded-2xl flex items-center justify-center text-white font-bold text-lg md:text-xl mb-2 shadow-lg">
               {config?.shopName?.charAt(0) || 'P'}
             </div>
          )}
          <span className="font-bold text-lg md:text-xl text-slate-800 text-center">{config?.shopName || 'ID Photo Booth'}</span>
       </div>

       <div className="max-w-4xl w-full bg-white rounded-3xl shadow-2xl overflow-hidden flex flex-col md:flex-row animate-fadeIn">

          <div className="w-full md:w-1/2 bg-slate-100 p-6 md:p-8 flex flex-col items-center justify-center border-b md:border-b-0 md:border-r border-slate-200 relative">
             <div className="absolute top-4 left-4 bg-white/80 backdrop-blur px-3 py-1 rounded-full text-xs font-bold text-slate-500 shadow-sm">
                ID: {photo.id}
             </div>

             <div className="relative shadow-2xl rounded-lg overflow-hidden border-4 border-white transform transition hover:scale-105 duration-300">
                 <img src={photo.dataUrl} className="max-h-[300px] md:max-h-[400px] w-auto object-contain" alt="ID Photo" />
             </div>

             <div className="mt-6 flex flex-wrap justify-center gap-3">
                <span className="px-3 py-1.5 bg-white border border-slate-200 text-slate-600 text-xs font-bold rounded-lg shadow-sm">
                   {photo.settings.size === PhotoSize.SIZE_3X4 ? '3x4 cm' : photo.settings.size === PhotoSize.SIZE_5X5 ? '5x5 cm' : '4x6 cm'}
                </span>
                <span className="px-3 py-1.5 bg-white border border-slate-200 text-slate-600 text-xs font-bold rounded-lg shadow-sm">
                   {new Date(photo.timestamp).toLocaleDateString('vi-VN')}
                </span>
             </div>
          </div>

          <div className="w-full md:w-1/2 p-6 md:p-8 flex flex-col">
             <div className="mb-6 md:mb-8 text-center md:text-left">
                <h2 className="text-xl md:text-2xl font-black text-slate-800 mb-2">Xin chào! 👋</h2>
                <p className="text-slate-500 text-sm">Ảnh của bạn đã sẵn sàng. Bạn có thể tải về điện thoại hoặc tải file in chất lượng cao để in ấn.</p>
             </div>

             <div className="flex-1 space-y-4">
                 <button 
                    onClick={handleDownloadSingle} 
                    className="group w-full p-4 bg-white border-2 border-slate-100 hover:border-brand-500 hover:bg-brand-50 rounded-2xl transition-all flex items-center gap-4 text-left shadow-sm hover:shadow-md active:scale-95"
                 >
                    <div className="w-10 h-10 md:w-12 md:h-12 rounded-full bg-blue-100 text-brand-600 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform">
                       <svg className="w-5 h-5 md:w-6 md:h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"></path></svg>
                    </div>
                    <div>
                       <div className="font-bold text-slate-800 group-hover:text-brand-700 text-sm md:text-base">Tải Ảnh Thẻ (PNG)</div>
                       <div className="text-xs text-slate-400">Ảnh đơn, Chất lượng gốc (HQ)</div>
                    </div>
                 </button>

                 <button 
                    onClick={handleDownloadSheet}
                    disabled={isGenerating} 
                    className="group w-full p-4 bg-brand-600 hover:bg-brand-700 rounded-2xl transition-all flex items-center gap-4 text-left shadow-lg shadow-brand-500/30 active:scale-95"
                 >
                    <div className="w-10 h-10 md:w-12 md:h-12 rounded-full bg-white/20 text-white flex items-center justify-center shrink-0">
                        {isGenerating ? (
                           <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                        ) : (
                           <svg className="w-5 h-5 md:w-6 md:h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z"></path></svg>
                        )}
                    </div>
                    <div>
                       <div className="font-bold text-white text-sm md:text-base">Tải File In (Sheet 13x18)</div>
                       <div className="text-xs text-brand-100 opacity-80">Đã dàn trang (PNG HQ)</div>
                    </div>
                 </button>
             </div>

             <div className="mt-8 pt-6 border-t border-slate-100 flex flex-col items-center">
                 <p className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-4">Quét mã để chia sẻ</p>
                 <div className="relative p-2 bg-white rounded-xl shadow-md border border-slate-100">
                    <img 
                      src={`https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(getCurrentUrl())}&color=000000&bgcolor=FFFFFF&margin=0&ecc=H`} 
                      className="w-28 h-28 md:w-32 md:h-32"
                      alt="QR"
                    />
                    {config?.logoUrl && (
                        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-8 h-8 bg-white rounded-full p-0.5 shadow-sm border border-slate-100 flex items-center justify-center">
                            <img src={config.logoUrl} className="w-full h-full object-contain rounded-full" alt="Logo" />
                        </div>
                    )}
                 </div>
             </div>
          </div>
       </div>

       <div className="mt-6 text-xs text-slate-400 font-medium text-center pb-8 flex flex-col items-center">
         {config?.logoUrl && (
             <img src={config.logoUrl} className="h-6 w-auto opacity-50 mb-2 grayscale" alt="Logo Footer" />
         )}
         <p>Hotline: {config?.contactPhone}</p>
         <p className="mt-1">© {new Date().getFullYear()} {config?.shopName || 'ID Photo Booth Pro'}</p>
       </div>
    </div>
  );
};

export default PhotoViewer;
